const require_index = require("../useDebounceFn/index.js");
let react = require("react");
//#region src/useDebounce/index.ts
const useDebounce = (value, wait, options) => {
	const [debounced, setDebounced] = (0, react.useState)(value);
	const { run } = require_index.useDebounceFn(() => {
		setDebounced(value);
	}, wait, options);
	(0, react.useEffect)(() => {
		run();
	}, [run, value]);
	return debounced;
};
//#endregion
exports.useDebounce = useDebounce;
